function combine(n,...t){return"first="+n+" rest=["+t.join(",")+"] arguments.length="+arguments.length}function reflectArguments(n,t){const r=[];for(let n=0;n<arguments.length;n++)r.push(arguments[n]);return r.join(",")}function mutateParamAffectsArguments(n){return n="mutated",arguments[0]}function restOnly(...n){return n.length+":"+n.join("-")}print(combine(1,2,3,4)),print(combine("only")),print(reflectArguments(1,2,3,4,5)),print("non-strict arguments aliasing:",mutateParamAffectsArguments("original")),print(restOnly()),print(restOnly(1,2,3));